    56	# --- locking -----------------------------------------------------------------
    57	# A named mutex, not a PID file: when the holding process is killed outright (which
    58	# is exactly what a Restart Manager shutdown does), Windows marks the mutex abandoned
    59	# and the next waiter acquires it cleanly. A PID file would be left behind as a stale
    60	# lock and would need heuristics to break.
    61	
    62	function New-KeystoneMutex {
    63	    param([Parameter(Mandatory)][string]$Name)
    64	    $safe = $Name -replace '[^A-Za-z0-9_-]', '_'
    65	    try {
    66	        [System.Threading.Mutex]::new($false, "Global\KeystoneOS-$safe")
    67	    } catch [System.UnauthorizedAccessException] {
    68	        # Global namespace can be denied by policy; a session-local mutex still gives
    69	        # mutual exclusion between the scheduled task and the reconciler.
    70	        [System.Threading.Mutex]::new($false, "Local\KeystoneOS-$safe")
    71	    }
    72	}
    73	
    74	function Invoke-WithMutex {
    75	    param(
    76	        [Parameter(Mandatory)][string]$Name,
    77	        [Parameter(Mandatory)][scriptblock]$Body,
    78	        [int]$TimeoutMs = 0,
    79	        [switch]$SkipIfBusy
    80	    )
    81	    $mutex = New-KeystoneMutex -Name $Name
    82	    $held = $false
    83	    try {
    84	        try {
    85	            $held = $mutex.WaitOne($TimeoutMs)
    86	        } catch [System.Threading.AbandonedMutexException] {
    87	            # Previous holder died without releasing. We now own it.
    88	            $held = $true
    89	        }
    90	        if (-not $held) {
    91	            if ($SkipIfBusy) { return $null }
    92	            throw "Could not acquire lock '$Name' within ${TimeoutMs}ms."
    93	        }
    94	        & $Body
    95	    }
    96	    finally {
    97	        if ($held) { try { $mutex.ReleaseMutex() } catch { } }
    98	        $mutex.Dispose()
    99	    }
   100	}
