114	    Why     = if ($unharvested -gt 0) {
115	                  "$unharvested decision(s) logged since the last ledger row — ship events recorded but not harvested"
116	              } else {
117	                  "nothing shipped since the last ledger row"
118	              }
119	}
120	
121	if ($Json) {
122	    $rituals | ConvertTo-Json -Depth 4
123	    exit 0
124	}
125	
126	Write-Host ""
