foreach ($op in 'Join-Path', 'Get-Item', 'Resolve-Path', 'Get-ChildItem', 'Split-Path', 'Convert-Path') {
    try {
        switch ($op) {
            'Join-Path'     { $null = Join-Path $u '.git' }
            'Get-Item'      { $null = Get-Item -LiteralPath $u -ErrorAction Stop }
            'Resolve-Path'  { $null = Resolve-Path $u -ErrorAction Stop }
            'Get-ChildItem' { $null = Get-ChildItem $u -ErrorAction Stop }
            'Split-Path'    { $null = Split-Path $u -Parent }
            'Convert-Path'  { $null = Convert-Path $u -ErrorAction Stop }
        }
        Write-Output ("  ok    {0}" -f $op)
    }
    catch { Write-Output ("  THROW {0}: {1}" -f $op, $_.Exception.Message) }
}

